let seq = 0;
const id = (p: string) => `${p}-${++seq}`;

// Monta o conteúdo do exemplo do ramo. "thumb" usa fotos menores (miniaturas da vitrine).
export function nicheDemo(niche: NicheId, size: DemoSize = 'full', name?: string): MiniContent {
  const info = nicheById(niche)!;
  const d = DEMOS[niche];
  const ph = (x: string) => photo(x, size);
  return {
    ...blankContent,
    theme: info.theme, palette: info.palette, niche, listTitle: info.listTitle,
    name: name?.trim() || d.name, headline: d.headline, tagline: d.tagline, ctaText: d.ctaText, ctaMessage: d.ctaMessage,
    description: d.description, mission: d.mission ?? '', vision: d.vision ?? '', values: d.values ?? '',
    address: d.address, hours: d.hours, cover: photo(d.cover, size, size === 'thumb' ? 560 : 1200),
    products: d.products.map(([n, desc, price, p]) => ({ id: id('p'), name: n, description: desc, price, image: p ? ph(p) : '' })),
    gallery: d.gallery.map(ph),
    benefits: d.benefits.map(([icon, title, text]) => ({ id: id('b'), icon, title, text })),
    stats: d.stats.map(([value, label]) => ({ id: id('s'), value, label })),
    testimonials: d.testimonials.map(([n, text]) => ({ id: id('t'), name: n, text, stars: 5 })),
    faq: d.faq.map(([q, a]) => ({ id: id('f'), q, a })),
    finalTitle: d.finalTitle, finalText: d.finalText, booking: d.booking ?? '', delivery: d.delivery ?? '',
  };
}

export const demoName = (niche: NicheId) => DEMOS[niche].name;
